// Cross-implementation parity for the colour palettes: every id × every valid
// index, diffed against the REAL desktop engine's output.
//
// The fixture is generated by tools/dump_palette_colors.py running
// glyphviz_core.color_palette.resolve_palette_color — regenerate it when either
// side's palette tables or gradient math change. Colours are integers, so this
// is an exact match, not a tolerance.

import { describe, expect, it } from 'vitest'
import fixture from './fixtures/palette_colors.json'
import { PALETTE_COUNT, PALETTE_NAMES, paletteIndexCount, resolvePaletteColor } from './colorPalette'

interface PaletteDump {
  id: number
  name: string
  index_count: number
  colors: number[][]
  out_of_range: Record<string, number[]>
}

const palettes = fixture.palettes as PaletteDump[]

describe('palette parity with the desktop engine', () => {
  it('dumps every palette', () => {
    expect(fixture.palette_count).toBe(PALETTE_COUNT)
    expect(palettes).toHaveLength(PALETTE_COUNT)
  })

  for (const dump of palettes) {
    describe(`palette ${dump.id} — ${dump.name}`, () => {
      it('has the same name and index range', () => {
        // The names are what the dropdown shows; the count sizes the Color
        // Index field and both cycle keys' wraparound.
        expect(PALETTE_NAMES[dump.id]).toBe(dump.name)
        expect(paletteIndexCount(dump.id)).toBe(dump.index_count)
      })

      it('resolves every index to the same colour', () => {
        const ours = Array.from({ length: dump.index_count }, (_, i) => {
          const { r, g, b } = resolvePaletteColor(dump.id, i)
          return [r, g, b]
        })
        expect(ours).toEqual(dump.colors)
      })

      it('wraps out-of-range indices the same way', () => {
        for (const [index, expected] of Object.entries(dump.out_of_range)) {
          const { r, g, b } = resolvePaletteColor(dump.id, Number(index))
          expect([r, g, b], `index ${index}`).toEqual(expected)
        }
      })
    })
  }
})
